"""The regression set (eval/regression.yaml): approved agent proposals that carry a question, in
the golden-set item format. Derived from system output, so it never feeds the verdict."""

from typing import Any

from enigram.domain.annotation import Annotation

HEADER = (
    "# Generated by `enigram regression export` from approved agent proposals (PRD Phase 5).\n"
    "# Not the golden set: never used for the verdict.\n"
)


def _approved(note: Annotation) -> bool:
    return (
        note.via == "mcp"
        and bool(note.question)
        and note.verified_by is not None
        # "proposed" again: edited by a key that may not verify, so the text is unreviewed
        and note.status not in ("rejected", "proposed")
    )


def _item(note: Annotation, repos: dict[int, dict[str, Any]]) -> dict[str, Any]:
    symbol = note.target_kind == "symbol"
    target = (
        note.target_ref.split("#", 1)[1] if symbol and "#" in note.target_ref else note.target_ref
    )
    item: dict[str, Any] = {
        "id": f"r{note.id:04d}",
        "category": "behavior_annotation",
        "split": "regression",
        "expected_route": "annotation",
    }
    repo = repos.get(note.repo_id) if symbol and note.repo_id is not None else None
    if repo:
        item["repo"] = {"url": repo["url"], "ref": repo["ref"], "sha": repo["indexed_sha"]}
    item |= {
        "setup": {"annotation": {"target": target, "text": note.text}},
        "question": note.question,
        "answer": note.text,
        "evidence": [{"symbol": target}] if symbol else [],
        "source": {
            "note": note.id,
            "proposed_by": note.author,
            "approved_by": note.verified_by,
            "approved_at": note.verified_at.isoformat() if note.verified_at else None,
            "memory_id": note.memory_id,
        },
    }
    return item


def regression_doc(notes: list[Annotation], repos: dict[int, dict[str, Any]]) -> dict[str, Any]:
    """Approved agent proposals with a question, oldest first: via "mcp", a question,
    verified_by set, status neither rejected nor proposed."""
    kept = sorted((n for n in notes if _approved(n)), key=lambda n: n.id)
    return {"version": 1, "questions": [_item(n, repos) for n in kept]}
